queries.query:
let NetworkEvents = materialize(
    _Im_NetworkSession
    | where EventVendor =~ "Zscaler" and EventProduct has "Private Access"
    | where isnotnull(NetworkBytes)
);
let AverageNetworkBytes = toscalar(NetworkEvents | summarize avg(todouble(NetworkBytes)));
NetworkEvents
| where todouble(NetworkBytes) > 1000.0 * AverageNetworkBytes
| extend ThresholdBytes = 1000.0 * AverageNetworkBytes
| project TimeGenerated, SrcUsername, SrcIpAddr, DstFQDN, DstIpAddr, NetworkBytes, ThresholdBytes
| extend AccountCustomEntity = SrcUsername

queries.description:
Shows the 20 ZPA App Connectors responsible for the most normalized network bytes.
Connector is a vendor-specific ZPA identifier retained as AdditionalFields.Connector;
byte volume is read from the standard ASIM NetworkBytes field.
